window.__posterData({"id": "hampus-edgren", "name": "Hampus Edgren", "folder": "Week1_Poster_HampusEdgren", "v": "2", "scripts": ["https://cdn.jsdelivr.net/npm/p5@2.3.4/lib/p5.js", "https://cdn.jsdelivr.net/npm/p5.sound@0.4.1/dist/p5.sound.min.js"], "links": [], "css": "html, body {\n  margin: 0;\n  padding: 0;\n}\ncanvas {\n  display: block;\n}\n", "code": "// Saccharine: Blood Ritual poster\n//\n// Interactions:\n//  - Click anywhere: the demonic circle spins faster, the orbs grow and it glows\n//  - Click \"Blood Ritual\" title area: blood drops appear\n//  - The phone rings now and then (it shakes and sends out red ring waves)\n//  - Click the phone to answer: it stops ringing and Ghostface slides in from the right\n//\n// Layout note: everything below (positions, click areas, state) is written in\n// the original 800x1000 \"design space\". It is converted to the real canvas size\n// only when drawing, so the canvas can be resized by changing CANVAS_WIDTH/HEIGHT.\n\n// ---------- Constants ----------\n\nconst CANVAS_WIDTH = 600;\nconst CANVAS_HEIGHT = 800;\n\nconst DESIGN_WIDTH = 800;\nconst DESIGN_HEIGHT = 1000;\n\n// Positions scale per axis so the layout fills the canvas the same way.\n// Sizes scale uniformly (by the smaller factor) so circles stay circles.\nconst SCALE_X = CANVAS_WIDTH / DESIGN_WIDTH;\nconst SCALE_Y = CANVAS_HEIGHT / DESIGN_HEIGHT;\nconst SCALE = Math.min(SCALE_X, SCALE_Y);\n\nconst RED = \"#ff0000\";\n\nconst DEFAULT_ORB_SIZE = 30;\nconst CLICK_ORB_SIZE = 50;\nconst DEFAULT_ROTATE_SPEED = 0.01;\nconst CLICK_ROTATE_SPEED = 0.1;\nconst SETTLE_RATE = 0.009; // how fast orb size / speed return to their defaults\n\n// Glow: the circle is drawn once per layer with a bigger blur each time, so the\n// light stacks up. Blur values are for full click speed and scale down with it.\nconst GLOW_LAYERS = [100, 55, 25];\nconst GLOW_COLOR = \"#ff2020\";\nconst GLOW_CORE_COLOR = \"#ffb0b0\"; // line color at full glow (fades back to red)\n\n// Halo: soft light that spills over the rest of the canvas\nconst HALO_RADIUS = 480;\nconst HALO_STRENGTH = 0.5; // peak opacity at full click speed\n\nconst GHOSTFACE_START_X = 1000; // off-screen to the right\nconst GHOSTFACE_STOP_X = 650;\nconst GHOSTFACE_SPEED = 5;\nconst GHOSTFACE_Y = 800;\n\n// Ringing phone (all in frames / design units)\nconst PHONE_POS = { x: 650, y: 350 };\nconst RING_CYCLE = 180; // a ring burst starts every this many frames\nconst RING_DURATION = 70; // ...and lasts this many frames\nconst RING_SHAKE_ANGLE = 0.1; // max tilt in radians\nconst RING_SHAKE_OFFSET = 3; // max sideways jitter\nconst RING_WAVES = 3; // ring arcs on each side of the phone\nconst RING_WAVE_PERIOD = 28; // frames for one arc to travel out and fade\nconst RING_START_RADIUS = 65;\nconst RING_TRAVEL = 45;\n\nconst BLOOD_DROP_COUNT = 20;\nconst BLOOD_MIN_SIZE = 10;\nconst BLOOD_MAX_SIZE = 40;\nconst BLOOD_FADE_RATE = 3;\n\nconst RITUAL_CENTER = { x: 400, y: 600 };\n\n// Clickable areas (edges are exclusive)\nconst PHONE_AREA = { left: 600, right: 700, top: 300, bottom: 400 };\nconst BLOOD_AREA = { left: 230, right: 390, top: 270, bottom: 310 };\n\n// Images drawn centered, in drawing order. The phone and Ghostface are handled\n// separately because they animate (the phone is drawn after these).\nconst STATIC_IMAGES = [\n  { name: \"star\", x: 100, y: 100 },\n  { name: \"pentagram\", x: 700, y: 150 },\n  { name: \"moon\", x: 180, y: 300 },\n  { name: \"starlight\", x: 90, y: 600 },\n  { name: \"starlight\", x: 710, y: 700 },\n];\n\nconst IMAGE_NAMES = [\"ghostface\", \"phone\", \"star\", \"pentagram\", \"moon\", \"starlight\"];\n\n// Each spoke of the circle: a line (x1, y1) -> (x2, y2) with an orb at (orbX, orbY).\n// Coordinates are relative to the circle's center.\nconst SPOKES = [\n  { x1: 0, y1: -150, x2: 0, y2: -200, orbX: 0, orbY: -220 }, // top\n  { x1: 0, y1: 150, x2: 0, y2: 200, orbX: 0, orbY: 220 }, // bottom\n  { x1: -150, y1: 0, x2: -200, y2: 0, orbX: -220, orbY: 0 }, // left\n  { x1: 150, y1: 0, x2: 200, y2: 0, orbX: 220, orbY: 0 }, // right\n  { x1: -106, y1: -106, x2: -141, y2: -141, orbX: -156, orbY: -156 }, // top left\n  { x1: 106, y1: -106, x2: 141, y2: -141, orbX: 156, orbY: -156 }, // top right\n  { x1: -106, y1: 106, x2: -141, y2: 141, orbX: -156, orbY: 156 }, // bottom left\n  { x1: 106, y1: 106, x2: 141, y2: 141, orbX: 156, orbY: 156 }, // bottom right\n];\n\n// ---------- State (all in design space) ----------\n\nconst images = {};\nlet ghostfaceX = GHOSTFACE_START_X;\nlet showGhostface = false;\n\nlet orbSize = DEFAULT_ORB_SIZE;\nlet rotateSpeed = DEFAULT_ROTATE_SPEED;\nlet rotationAngle = 0;\n\nlet bloodDrops = [];\n\n// ---------- p5 lifecycle ----------\n\nasync function setup() {\n  createCanvas(CANVAS_WIDTH, CANVAS_HEIGHT);\n\n  // Load all images in parallel\n  await Promise.all(\n    IMAGE_NAMES.map(async (name) => {\n      images[name] = await loadImage(`${name}.png`);\n    })\n  );\n}\n\nfunction mousePressed() {\n  // Any click boosts the demonic circle\n  orbSize = CLICK_ORB_SIZE;\n  rotateSpeed = CLICK_ROTATE_SPEED;\n\n  if (isMouseInside(PHONE_AREA)) {\n    showGhostface = true;\n  }\n\n  if (isMouseInside(BLOOD_AREA)) {\n    spawnBlood();\n  }\n}\n\nfunction draw() {\n  background(0);\n\n  drawImages();\n  drawBlood();\n  drawHalo();\n  drawText();\n  drawDemonicCircle();\n}\n\n// ---------- Helpers ----------\n\n// Design space -> canvas space\nfunction toX(x) {\n  return x * SCALE_X;\n}\n\nfunction toY(y) {\n  return y * SCALE_Y;\n}\n\nfunction toSize(size) {\n  return size * SCALE;\n}\n\nfunction isMouseInside(area) {\n  // Compare in design space, since the areas are defined there\n  const x = mouseX / SCALE_X;\n  const y = mouseY / SCALE_Y;\n  return x > area.left && x < area.right && y > area.top && y < area.bottom;\n}\n\nfunction spawnBlood() {\n  for (let i = 0; i < BLOOD_DROP_COUNT; i++) {\n    bloodDrops.push({\n      x: random(BLOOD_AREA.left, BLOOD_AREA.right),\n      y: random(BLOOD_AREA.top, BLOOD_AREA.bottom),\n      size: random(BLOOD_MIN_SIZE, BLOOD_MAX_SIZE),\n      alpha: 255,\n    });\n  }\n}\n\n// Draws an image centered at a design-space position, scaled with the canvas\nfunction drawImageAt(img, x, y) {\n  image(img, toX(x), toY(y), toSize(img.width), toSize(img.height));\n}\n\n// ---------- Drawing ----------\n\n// The phone rings in bursts until it is answered (clicked)\nfunction drawPhone() {\n  const x = toX(PHONE_POS.x);\n  const y = toY(PHONE_POS.y);\n  const img = images.phone;\n\n  const cycleFrame = frameCount % RING_CYCLE;\n  const ringing = !showGhostface && cycleFrame < RING_DURATION;\n\n  let angle = 0;\n  let offset = 0;\n  if (ringing) {\n    // Shake builds up and dies down over the burst\n    const envelope = sin((PI * cycleFrame) / RING_DURATION);\n    angle = sin(frameCount * 1.4) * RING_SHAKE_ANGLE * envelope;\n    offset = sin(frameCount * 2.1) * RING_SHAKE_OFFSET * envelope;\n\n    drawRingWaves(x, y, envelope);\n  }\n\n  push();\n  translate(x + toSize(offset), y);\n  rotate(angle);\n  image(img, 0, 0, toSize(img.width), toSize(img.height));\n  pop();\n}\n\n// Red arcs that travel outward from both sides of the phone and fade\nfunction drawRingWaves(x, y, envelope) {\n  push();\n  noFill();\n  strokeWeight(toSize(3));\n  strokeCap(ROUND);\n\n  for (let i = 0; i < RING_WAVES; i++) {\n    const t = ((frameCount + (i * RING_WAVE_PERIOD) / RING_WAVES) % RING_WAVE_PERIOD) / RING_WAVE_PERIOD;\n    const diameter = toSize(2 * (RING_START_RADIUS + t * RING_TRAVEL));\n    stroke(255, 0, 0, 255 * (1 - t) * envelope);\n\n    arc(x, y, diameter, diameter, -PI * 0.2, PI * 0.2); // right side\n    arc(x, y, diameter, diameter, PI * 0.8, PI * 1.2); // left side\n  }\n\n  pop();\n}\n\nfunction drawImages() {\n  imageMode(CENTER);\n\n  for (const { name, x, y } of STATIC_IMAGES) {\n    drawImageAt(images[name], x, y);\n  }\n  drawPhone();\n  // Ghostface is drawn last so he appears on top of the phone\n  drawImageAt(images.ghostface, ghostfaceX, GHOSTFACE_Y);\n\n  if (showGhostface && ghostfaceX > GHOSTFACE_STOP_X) {\n    ghostfaceX -= GHOSTFACE_SPEED;\n  }\n}\n\nfunction drawBlood() {\n  noStroke();\n  for (const drop of bloodDrops) {\n    fill(180, 0, 0, drop.alpha);\n    circle(toX(drop.x), toY(drop.y), toSize(drop.size));\n    drop.alpha -= BLOOD_FADE_RATE;\n  }\n}\n\nfunction drawText() {\n  textAlign(CENTER);\n  noStroke();\n  fill(RED);\n  textFont(\"Georgia\");\n\n  // Title\n  textSize(toSize(92));\n  textStyle(BOLD);\n  text(\"SACCHARINE\", toX(400), toY(250));\n\n  // Subtitle\n  textSize(toSize(64));\n  textStyle(NORMAL);\n  text(\"Blood Ritual\", toX(400), toY(310));\n\n  // Date\n  textSize(toSize(92));\n  text(\"11/18\", toX(150), toY(950));\n}\n\n// 0 at normal speed, 1 right after a click, fading as the speed settles back\nfunction getSpeedBoost() {\n  return constrain(\n    (rotateSpeed - DEFAULT_ROTATE_SPEED) /\n      (CLICK_ROTATE_SPEED - DEFAULT_ROTATE_SPEED),\n    0,\n    1\n  );\n}\n\n// Light that lightens everything around the circle (adds on top of the canvas)\nfunction drawHalo() {\n  const boost = getSpeedBoost();\n  if (boost <= 0) return;\n\n  const x = toX(RITUAL_CENTER.x);\n  const y = toY(RITUAL_CENTER.y);\n  const gradient = drawingContext.createRadialGradient(\n    x, y, 0,\n    x, y, toSize(HALO_RADIUS)\n  );\n  gradient.addColorStop(0, `rgba(255, 40, 40, ${HALO_STRENGTH * boost})`);\n  gradient.addColorStop(0.5, `rgba(255, 20, 20, ${HALO_STRENGTH * 0.4 * boost})`);\n  gradient.addColorStop(1, \"rgba(255, 0, 0, 0)\");\n\n  push();\n  blendMode(ADD);\n  noStroke();\n  drawingContext.fillStyle = gradient;\n  rect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);\n  pop();\n}\n\n// The rings, spokes and orbs themselves (uses the current stroke / shadow).\n// Drawn in design-sized units inside a scaled transform, so line weight shrinks too.\nfunction drawRitualShape() {\n  push();\n  translate(toX(RITUAL_CENTER.x), toY(RITUAL_CENTER.y));\n  scale(SCALE);\n\n  circle(0, 0, 300);\n  circle(0, 0, 400);\n\n  push();\n  rotate(rotationAngle);\n  for (const s of SPOKES) {\n    line(s.x1, s.y1, s.x2, s.y2);\n    circle(s.orbX, s.orbY, orbSize);\n  }\n  pop();\n\n  pop();\n}\n\nfunction drawDemonicCircle() {\n  const boost = getSpeedBoost();\n\n  noFill();\n  strokeWeight(2);\n\n  // Glow layers: biggest blur first, stacking up the light\n  if (boost > 0) {\n    stroke(GLOW_COLOR);\n    drawingContext.shadowColor = GLOW_COLOR;\n    for (const blur of GLOW_LAYERS) {\n      drawingContext.shadowBlur = toSize(blur) * boost;\n      drawRitualShape();\n    }\n    drawingContext.shadowBlur = 0; // nothing else should glow\n  }\n\n  // Crisp line on top; it brightens toward a hot core while the glow is strong\n  stroke(lerpColor(color(RED), color(GLOW_CORE_COLOR), boost));\n  drawRitualShape();\n\n  // Ease orb size and rotation speed back to their defaults\n  orbSize = lerp(orbSize, DEFAULT_ORB_SIZE, SETTLE_RATE);\n  rotateSpeed = lerp(rotateSpeed, DEFAULT_ROTATE_SPEED, SETTLE_RATE);\n  rotationAngle += rotateSpeed;\n}\n\n//Reflection/critique\n//One thing the AI did differently than me was that it split almost everything into separate functions. Originally I just had most things happening directly in draw and mousepressed. Now there are functions for the phone, blood, text, glow effects, circles and so on. It definitely looks more organized although if I'm being honest it also makes me scroll a lot more to find things. If I had to simplify what the AI did it is that it took what I already had but organized it into a much organized sutructure. When I code it's like having a messy desk. People looking at it get worried but to me everything has its place and I know where to find it. The AI is like my boss that decided to clean the desk and neatly organize every item.\n\n//I specifically asked for the circle to have more of a glow effect when clicked. Instead of just changing the color, the AI decided to make multiple glow layers, a halo effect, and even introduced shadow blur. I wouldn't have known how to do that myself, but I think the final result looks much closer to the supernatural vibe I wanted for the poster.\n\n//Something else the AI chose to do on its own was create constants for basically everything. My original code mostly used numbers directly whenever I needed them. Now things like orb size, glow strength, phone ringing and blood drop settings all have their own named values at the top. At first it felt a bit excessive, but I can see why it is useful since changing values later becomes a lot easier.\n\n//I also asked for it to change the scale of the canvas since mine was 1000x800 and this assignment asked for 800x600. The AI solved this in a way I never would have thought of by creating a separate \"design space\" and then converting positions to the actual canvas size. I don't completely understand every part of he scaling system yet, but it works, and honestly that's much better than having to edit the size and position one by one :').\n\n//The ringing phone was an addition the AI came up with itself. The AI added shaking, animated ring waves and timing cycles. I didn't specifically ask for all of that, but I think it helps draw attention to the phone and makes the interaction easier to notice.\n\n//Looking at the final version in the same way we have done design critiques in class, I think the strongest improvement is feedback. Clicking things now gives a much clearer response than before. The glowing ritual circle, blood effect and ringing phone all make interactions easier to understand. The main weakness is probably complexity. The code is cleaner from a programming perspective, but it is also much longer and a little harder for me personally to follow compared to my original version. Overall though, I think the changes improved both the visual presentation and the interactivity without changing the original idea of the poster.\n\n//As a final not I hope the text doesn't look awful to you since in p5 it changes line when the text comes to the edge of the box. Not sure how that translates if you read the code with somethingelse.\n", "assets": {"pentagram.png": {"mime": "image/webp", "b64": ""}, "phone.png": {"mime": "image/webp", "b64": ""}, "star.png": {"mime": "image/webp", "b64": ""}, "ghostface.png": {"mime": "image/webp", "b64": ""}, "moon.png": {"mime": "image/webp", "b64": ""}, "starlight.png": {"mime": "image/webp", "b64": ""}}});
